303	  - [x] `seed-b-backend.Api/Controllers/CartController.cs` (NEU) — eigener Controller, folgt der Architektur-Kapazitätskarte („FR-8, FR-9 (cart add / view / edit) | `CartService` + `CartController` | AD-1, AD-2"):
304	    ```csharp
305	    using Microsoft.AspNetCore.Mvc;
306	    using seed_b_backend.Api.Application;
307	    using seed_b_backend.Api.Controllers.Dtos;
308	
309	    namespace seed_b_backend.Api.Controllers;
310	
311	    [ApiController]
312	    [Route("api/cart")]
313	    public class CartController(CartService cartService) : ControllerBase
314	    {
315	        [HttpPost("items")]
316	        public async Task<ActionResult<CartDto>> AddItem(
317	            [FromHeader(Name = "X-Cart-Id")] string? cartId,
318	            [FromBody] AddCartItemRequest request,
319	            CancellationToken ct = default)
320	        {
321	            var parsedCartId = Guid.TryParse(cartId, out var parsed) ? parsed : (Guid?)null;
322	
323	            var result = await cartService.AddItemAsync(parsedCartId, request.ProductId, request.SupplierId, request.Quantity, ct);
324	            if (result is null)
325	            {
326	                return NotFound();
327	            }
328	
329	            return Ok(new CartDto
330	            {
331	                CartId = result.CartId,
332	                TotalPrice = result.TotalPrice,
333	                Items = result.Items
334	                    .Select(l => new CartItemDto
335	                    {
336	                        ProductId = l.ProductId,
337	                        SupplierId = l.SupplierId,
