    ```csharp
    using Microsoft.EntityFrameworkCore;
    using seed_b_backend.Api.Data;
    using seed_b_backend.Api.Domain;

    namespace seed_b_backend.Api.Application;

    public class CartService(AppDbContext context)
    {
        public async Task<CartResult?> AddItemAsync(
            Guid? cartId,
            string productId,
            string supplierId,
            int quantity,
            CancellationToken ct = default)
        {
            var offerExists = await context.Offers
                .AnyAsync(o => o.ProductId == productId && o.SupplierId == supplierId, ct);
            if (!offerExists)
            {
                return null;
            }

            var resolvedCartId = cartId is not null && await context.Carts.AnyAsync(c => c.Id == cartId, ct)
                ? cartId.Value
                : await CreateCartAsync(ct);

            var updatedRows = await context.CartItems
                .Where(ci => ci.CartId == resolvedCartId && ci.ProductId == productId && ci.SupplierId == supplierId)
                .ExecuteUpdateAsync(s => s.SetProperty(ci => ci.Quantity, ci => ci.Quantity + quantity), ct);

            if (updatedRows == 0)
            {
                var newItem = new CartItem { CartId = resolvedCartId, ProductId = productId, SupplierId = supplierId, Quantity = quantity };
                context.CartItems.Add(newItem);
                try
                {
                    await context.SaveChangesAsync(ct);
                }
                catch (DbUpdateException)
                {
                    // Ein gleichzeitiges Hinzufügen desselben Produkt-Lieferant-Paars zu
                    // diesem Warenkorb hat seine Zeile zwischen unserem ExecuteUpdateAsync
                    // (traf nichts) und diesem Add eingefügt — der DB-Unique-Constraint
                    // (zusammengesetzter Primärschlüssel, AD-1) lehnt unseren Insert ab,
                    // statt still zu duplizieren. Fallback: Update, das jetzt garantiert
                    // genau diese Zeile trifft. Identisches Muster wie RatingService
                    // (Story 2.3) für den AD-5-Race.
                    context.Entry(newItem).State = EntityState.Detached;
                    var raceFallbackRows = await context.CartItems
                        .Where(ci => ci.CartId == resolvedCartId && ci.ProductId == productId && ci.SupplierId == supplierId)
                        .ExecuteUpdateAsync(s => s.SetProperty(ci => ci.Quantity, ci => ci.Quantity + quantity), ct);

                    if (raceFallbackRows == 0)
                    {
                        throw;
                    }
                }
            }

            return await BuildCartResultAsync(resolvedCartId, ct);
        }

        private async Task<Guid> CreateCartAsync(CancellationToken ct)
        {
            var cart = new Cart { Id = Guid.NewGuid() };
            context.Carts.Add(cart);
            await context.SaveChangesAsync(ct);
            return cart.Id;
        }

        private async Task<CartResult> BuildCartResultAsync(Guid cartId, CancellationToken ct)
        {
            var lines = await context.CartItems
                .Where(ci => ci.CartId == cartId)
                .Join(context.Offers,
                    ci => new { ci.ProductId, ci.SupplierId },
                    o => new { o.ProductId, o.SupplierId },
                    (ci, o) => new CartResultLine
                    {
                        ProductId = ci.ProductId,
                        SupplierId = ci.SupplierId,
                        Quantity = ci.Quantity,
                        UnitPrice = o.Price
                    })
                .ToListAsync(ct);

            return new CartResult
            {
                CartId = cartId,
                Items = lines,
                TotalPrice = lines.Sum(l => l.UnitPrice * l.Quantity)
            };
        }
    }
    ```
    - **Reihenfolge bewusst: Offer-Existenzprüfung VOR Cart-Auflösung/-Anlage (AC 5):** Verhindert, dass eine Anfrage mit unbekanntem Produkt-Lieferant-Paar einen leeren `Cart`-Datensatz anlegt, bevor der Fehler erkannt wird — identisches „reject immediately, no side effect first"-Prinzip wie AD-3 für die Bestellung („rejects immediately if the cart has zero lines or any line has an invalid quantity"). Ohne diese Reihenfolge könnte ein Gast durch wiederholte ungültige Anfragen beliebig viele leere `Cart`-Zeilen erzeugen.
    - **Der Join in `BuildCartResultAsync` ist ein Inner Join — implementiert bereits einen Teil von AD-2:** „A `CartItem` whose `Offer` no longer exists is excluded from the returned lines/total on a read." Da der `Join` hier direkt gegen `Offer` filtert, wird eine `CartItem`-Zeile ohne (mittlerweile entferntes) `Offer` automatisch nicht zurückgegeben — identisches Verhalten wie von AD-2 für Story 3.2 gefordert, hier als Nebeneffekt der Query-Form bereits korrekt. `BuildCartResultAsync` ist so geschrieben, dass Story 3.2 sie direkt für den `GET`-Endpunkt wiederverwenden kann (AD-2: „the one place this resolution happens, reused by every cart-reading path") — bei Bedarf um Produkt-/Lieferantennamen erweitern (`Include`/zusätzlicher Join), nicht neu erfinden.
    - **`cartId is not null && await context.Carts.AnyAsync(...)` statt reinem Null-Check:** Deckt sowohl „kein Header" als auch „Header mit unbekannter/fremder GUID" in einer Bedingung ab (AC 6) — beide Fälle führen zu `CreateCartAsync()`. Der Controller (Task 3) ist dafür verantwortlich, einen syntaktisch ungültigen Header-Wert (kein GUID-Format) bereits vorher auf `null` zu normalisieren (`Guid.TryParse`), sodass hier nur noch zwischen „gültige, existierende GUID" und „alles andere" unterschieden werden muss.
    - **Kein App-seitiges Check-then-Insert auf `CartItem` (identisches Prinzip zu AD-5/RatingService):** Der Rückgabewert von `ExecuteUpdateAsync` entscheidet über den Zweig, der DB-Unique-Constraint (zusammengesetzter Primärschlüssel) fängt den verbleibenden Race über `catch (DbUpdateException)` ab — zu jedem Zeitpunkt maximal eine Zeile pro `(CartId, ProductId, SupplierId)`.
