    ```typescript
    import { HttpErrorResponse } from '@angular/common/http';
    import { Component, inject, signal } from '@angular/core';

    import { CartService } from '../../../core/cart.service';
    import { CartApiService } from '../cart-api.service';
    import { Cart } from '../cart.model';

    @Component({
      selector: 'app-cart-view',
      templateUrl: './cart-view.html'
    })
    export class CartView {
      private cartApi = inject(CartApiService);
      private cartService = inject(CartService);

      protected readonly cart = signal<Cart | null>(null);
      protected readonly loading = signal(true);
      protected readonly error = signal<string | null>(null);
      protected readonly busyKey = signal<string | null>(null);

      constructor() {
        this.loading.set(true);
        this.cartApi.getCart(this.cartService.cartId()).subscribe({
          next: (cart) => {
            this.cart.set(cart);
            this.loading.set(false);
          },
          error: () => {
            this.loading.set(false);
            this.error.set('Warenkorb konnte nicht geladen werden.');
          }
        });
      }

      protected lineKey(productId: string, supplierId: string): string {
        return `${productId}:${supplierId}`;
      }

      protected isBusy(productId: string, supplierId: string): boolean {
        return this.busyKey() === this.lineKey(productId, supplierId);
      }

      protected updateQuantity(productId: string, supplierId: string, quantityRaw: string): void {
        const cartId = this.cartService.cartId();
        const quantity = Number(quantityRaw);
        if (!cartId || !Number.isInteger(quantity) || quantity < 1) {
          this.error.set('Bitte eine gültige Menge (mindestens 1) angeben.');
          return;
        }

        this.busyKey.set(this.lineKey(productId, supplierId));
        this.error.set(null);

        this.cartApi.updateQuantity(cartId, productId, supplierId, quantity).subscribe({
          next: (cart) => {
            this.cart.set(cart);
            this.busyKey.set(null);
          },
          error: (err: HttpErrorResponse) => {
            this.busyKey.set(null);
            this.error.set(err.status === 409 ? 'Angebot nicht mehr verfügbar' : 'Menge konnte nicht geändert werden.');
          }
        });
      }

      protected removeItem(productId: string, supplierId: string): void {
        const cartId = this.cartService.cartId();
        if (!cartId) {
          return;
        }

        this.busyKey.set(this.lineKey(productId, supplierId));
        this.error.set(null);

        this.cartApi.removeItem(cartId, productId, supplierId).subscribe({
          next: (cart) => {
            this.cart.set(cart);
            this.busyKey.set(null);
          },
          error: () => {
            this.busyKey.set(null);
            this.error.set('Position konnte nicht entfernt werden.');
          }
        });
      }
    }
    ```
    - **`updateQuantity`/`removeItem` prüfen `cartId` clientseitig, obwohl `CartApiService` das bereits typmäßig erzwingt:** Die Buttons/Inputs in der Vorlage sind nur innerhalb eines `@for`-Blocks über `cart().items` erreichbar, der bei `cartId === null` immer leer ist — der Check ist reine Verteidigung in der Tiefe (identisches Prinzip wie `ProductDetail.addToCart`, Story 3.1), kein aktuell erreichbarer Pfad.
    - **Ein einzelnes `busyKey`-Signal statt pro-Zeile-Boolean-Map:** Es kann jeweils nur eine Zeilen-Interaktion gleichzeitig laufen (kein Multi-Request-UI vorgesehen) — ein einzelner „welche Zeile ist gerade aktiv"-Schlüssel reicht, identisches Minimalismus-Prinzip wie das bereits etablierte `submitting`/`addingToCart`-Boolean-Trio (Story 2.3/3.1), hier nur um einen Zeilen-Schlüssel statt eines globalen Flags erweitert, weil mehrere Zeilen gleichzeitig existieren.
