    private async Task<CartResult> BuildCartResultAsync(Guid cartId, CancellationToken ct)
    {
        var lines = await context.CartItems
            .Where(ci => ci.CartId == cartId)
            .Join(context.Offers,
                ci => new { ci.ProductId, ci.SupplierId },
                o => new { o.ProductId, o.SupplierId },
                (ci, o) => new CartResultLine
                {
                    ProductId = ci.ProductId,
                    ProductName = o.Product!.Name,
                    SupplierId = ci.SupplierId,
                    SupplierName = o.Supplier!.Name,
                    Quantity = ci.Quantity,
                    UnitPrice = o.Price
                })
            .ToListAsync(ct);

        return new CartResult
        {
            CartId = cartId,
            Items = lines,
            TotalPrice = lines.Sum(l => l.UnitPrice * l.Quantity)
        };
    }
    ```
    - **Kein zusätzliches `Include`/`Join` gegen `Products`/`Suppliers` nötig:** `o.Product!.Name`/`o.Supplier!.Name` innerhalb der Projektion auf `context.Offers` lässt EF Core den nötigen Join automatisch generieren — identischer, bereits im Projekt etablierter Pattern (siehe `ProductsController.GetProduct`, Zeile `o.Supplier!.Name`).
